import re

_PHONE_RE = re.compile(r'(?<!\d)(0\d{1,2}[-\s]?)\d{4}(?=[-\s]?\d{4}(?!\d))')

def mask_phone(text):
    if not isinstance(text, str):
        return text
    return _PHONE_RE.sub(r'\1****', text)

